@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700;800&family=Nunito:wght@600;700;800;900&display=swap');
:root{--ink:#293b32;--muted:#75877a;--green:#528668;--deep:#38664d;--lime:#d8e9a1;--cream:#fffdf6;--line:#e8ecdf;--shadow:0 12px 35px #345d3d12}*{box-sizing:border-box}body{margin:0;background:#f4f7ed;color:var(--ink);font-family:'DM Sans',sans-serif;min-height:100vh;background-image:radial-gradient(ellipse at 12% 9%,#e4f0d7 0,transparent 31%),radial-gradient(ellipse at 95% 78%,#e8efdc 0,transparent 32%)}button{font:inherit;color:inherit;cursor:pointer}.app-shell{max-width:1280px;margin:0 auto;padding:0 46px 24px}.topbar{height:83px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #dfe8d8}.brand{display:flex;gap:11px;align-items:center;text-decoration:none;color:var(--ink);font-family:Nunito,sans-serif;font-size:19px;font-weight:700;letter-spacing:-.4px}.brand b{font-weight:900;color:#4f805f}.brand-mark{display:grid;place-items:center;background:#e1ecc7;color:#578164;width:36px;height:36px;border-radius:13px;font-size:22px}.top-stats{display:flex;align-items:center;gap:10px}.stat-pill{height:39px;background:#fff;border:1px solid #e8ecdf;border-radius:22px;padding:0 13px;display:flex;align-items:center;gap:6px;box-shadow:0 3px 12px #29483108}.stat-pill>span{color:#e4ae43;font-size:15px}.stat-pill b{font-size:13px}.stat-pill small{font-size:9px;letter-spacing:.8px;color:#859085;font-weight:700}.berry-pill>span{color:#e27d70}.icon-button{width:38px;height:38px;border:1px solid #e8ecdf;background:#fff;border-radius:13px;color:#64866d}.sound-toggle{font-size:19px}.layout{display:grid;grid-template-columns:minmax(0,1.56fr) minmax(340px,.9fr);gap:30px;padding:35px 0 15px}.play-column{min-width:0}.welcome-row{display:flex;justify-content:space-between;align-items:center;margin-bottom:20px}.eyebrow{margin:0 0 7px;font-size:9px;font-weight:800;letter-spacing:1.55px;color:#86a080}.welcome-row h1{font:900 34px/1.1 Nunito,sans-serif;letter-spacing:-1.1px;margin:0;color:#2d4235}.subtitle{font-size:12px;color:#718174;margin:7px 0 0}.weather{display:flex;align-items:center;gap:9px;padding:9px 13px;background:#fff9e8;border:1px solid #f1e8ca;border-radius:14px}.weather>span{font-size:22px;color:#ecb748}.weather b,.weather small{display:block}.weather b{font-size:10px}.weather small{font-size:9px;color:#9a987d;margin-top:3px}.zone-tabs{display:flex;gap:8px;overflow-x:auto;scrollbar-width:none;margin-bottom:12px;padding-bottom:2px}.zone-tabs::-webkit-scrollbar{display:none}.zone-tab{flex:none;padding:9px 13px;border:1px solid #e5eadd;background:#ffffffa8;border-radius:12px;color:#718071;font-size:11px;font-weight:700;transition:.2s}.zone-tab span{margin-right:5px;font-size:13px}.zone-tab.active{background:#527f60;border-color:#527f60;color:white;box-shadow:0 5px 12px #527f6030}.meadow-card{background:var(--cream);border:1px solid #e9eddc;border-radius:21px;padding:14px;box-shadow:var(--shadow);overflow:hidden}.scene-top{height:25px;display:flex;align-items:flex-start;justify-content:space-between;padding:1px 5px 0}.location-tag{font-size:10px;font-weight:800;color:#526b58;display:flex;align-items:center;gap:6px}.location-tag i{width:7px;height:7px;background:#86b876;border-radius:50%;box-shadow:0 0 0 3px #e2efd9}.scene-time{font-size:8px;font-weight:800;color:#a6a88f;letter-spacing:.8px}#meadow{width:100%;height:278px;display:block;border-radius:15px;cursor:pointer;touch-action:manipulation}.scene-caption{display:flex;justify-content:space-between;align-items:center;padding:11px 5px 13px;font-size:10px;color:#7a8a78}.scene-caption>span:first-child{display:flex;align-items:center;gap:6px}.tap-hint{font-size:8px;letter-spacing:.7px;font-weight:800;color:#99a490}.tap-hint b{font-size:13px;color:#78a277;margin-left:4px}.explore-action{display:flex;align-items:center;gap:14px;border-top:1px solid #edf0e7;padding:13px 3px 1px}.primary-button{display:flex;align-items:center;gap:11px;text-align:left;background:#528467;color:#fff;border:0;border-radius:13px;padding:10px 13px;min-width:226px;box-shadow:0 5px 13px #50826031;transition:transform .15s,background .15s}.primary-button:hover{background:#416f53;transform:translateY(-1px)}.primary-button:active{transform:translateY(1px)}.button-icon{width:31px;height:31px;border-radius:10px;background:#ffffff24;display:grid;place-items:center;font-size:21px}.primary-button b,.primary-button small{display:block}.primary-button b{font-size:11px}.primary-button small{font-size:9px;color:#d9e8dc;margin-top:3px}.button-arrow{margin-left:auto;font-size:18px}.search-note{font-size:9px;color:#9aa293}.search-note span{color:#d6ad56;font-size:15px;margin-left:4px}.field-note{display:flex;align-items:center;gap:12px;padding:13px 15px;margin-top:12px;background:#ebf2e3;border:1px solid #e2ead7;border-radius:14px}.note-icon{font-size:18px}.field-note p{margin:0;display:grid;gap:3px;flex:1}.field-note p b{font-size:10px;color:#536d56}.field-note p span{font-size:9px;color:#81917d}.note-stars{color:#b7c88c;font-size:17px}.journal-card{background:#fffefa;border:1px solid #e9eddc;border-radius:21px;padding:22px 21px 14px;box-shadow:var(--shadow);align-self:stretch}.journal-heading{display:flex;justify-content:space-between;align-items:center}.journal-heading .eyebrow{font-size:8px;margin-bottom:6px}.journal-heading h2{font:900 21px Nunito,sans-serif;letter-spacing:-.5px;margin:0}.journal-heading h2 span{color:#e2b750;font-size:15px;margin-left:3px}.text-button{border:0;background:none;color:#718c72;font-size:9px;font-weight:700;padding:5px}.text-button span{font-size:13px;margin-left:4px}.progress-block{margin-top:20px;padding:13px 13px 11px;background:#f7f8f0;border:1px solid #edf0e4;border-radius:13px}.progress-copy{display:flex;align-items:center;justify-content:space-between}.progress-copy>span{font-size:8px;letter-spacing:.9px;font-weight:800;color:#8a9988}.progress-copy b{font:900 16px Nunito;color:#4c7959}.progress-copy i{font-style:normal;color:#a6b0a1;font-size:11px}.progress-track{height:6px;background:#e4eadc;border-radius:5px;margin:8px 0 7px;overflow:hidden}.progress-track div{height:100%;width:0;background:linear-gradient(90deg,#79ad72,#b6ce7b);border-radius:5px;transition:width .5s}.progress-block p{margin:0;color:#99a292;font-size:9px}.collection-grid{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:8px 7px;margin:15px 0 14px}.creature-slot{border:1px solid #edf0e8;background:#fbfcf8;border-radius:12px;min-height:76px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:5px;cursor:pointer;transition:transform .16s,border .16s,background .16s;padding:6px 2px}.creature-slot:hover{transform:translateY(-2px);border-color:#cdddbf}.creature-slot .slot-art{font-size:24px;line-height:1;filter:saturate(.88)}.creature-slot .slot-name{font-size:8px;font-weight:700;color:#788679;max-width:100%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.creature-slot.unknown{background:#f5f6f1;border-style:dashed}.creature-slot.unknown .slot-art{width:29px;height:29px;display:grid;place-items:center;border-radius:10px;background:#eaeee4;color:#afb9a9;font-size:17px}.creature-slot.unknown .slot-name{color:#a7afa1}.creature-slot.new-friend{background:#f0f7e9;border-color:#dbe9ce}.journal-footer{border-top:1px solid #edf0e8;padding:12px 2px 0;display:flex;align-items:center;gap:7px;font-size:9px;color:#8a9787}.legend-dot{width:8px;height:8px;background:#80ad77;border-radius:50%}.footer-total{margin-left:auto;font-weight:800;color:#6b886b}.bottom-note{text-align:center;color:#a3ad9c;font-size:9px;padding:11px}.bottom-note span{color:#aec88f;margin:0 8px}.modal-backdrop{position:fixed;inset:0;z-index:5;background:#23382fb0;backdrop-filter:blur(5px);display:grid;place-items:center;padding:20px}.hidden{display:none!important}.encounter-modal{width:min(420px,100%);background:#fffdf7;border-radius:23px;padding:20px;box-shadow:0 24px 70px #162c1e55;position:relative;text-align:center;animation:pop .25s ease-out}@keyframes pop{from{transform:translateY(12px) scale(.97);opacity:0}to{transform:none;opacity:1}}.modal-close{position:absolute;right:13px;top:13px;width:30px;height:30px;border:0;background:#f0f3e9;border-radius:10px;color:#768674;font-size:17px}.encounter-art{height:155px;border-radius:17px;background:linear-gradient(180deg,#e4f3d9,#f2f6d9);display:grid;place-items:center;margin-bottom:16px;position:relative;overflow:hidden}.encounter-art:before,.encounter-art:after{content:'✦';position:absolute;color:#fff9;font-size:23px;top:26px;left:25%}.encounter-art:after{content:'✧';left:auto;right:23%;top:51px}.big-creature{font-size:82px;filter:drop-shadow(0 11px 7px #314d2c24);animation:bob 2s ease-in-out infinite}@keyframes bob{50%{transform:translateY(-7px) rotate(3deg)}}.modal-rarity{display:inline-block;padding:5px 9px;border-radius:20px;background:#eff4e5;color:#77926e;font-size:8px;font-weight:800;letter-spacing:.9px}.encounter-modal h2{font:900 25px Nunito;margin:8px 0 4px}.encounter-modal .description{font-size:11px;color:#819080;margin:0 auto 13px;max-width:280px;line-height:1.55}.affinity{font-size:9px;color:#99a18d;margin:0 0 14px}.affinity b{color:#cb8b4d}.encounter-actions{display:grid;grid-template-columns:1fr 1.2fr;gap:9px}.secondary-button,.catch-button{border-radius:12px;padding:11px 9px;font-size:10px;font-weight:800}.secondary-button{border:1px solid #e5eadc;background:#fff;color:#688269}.catch-button{border:0;background:#558767;color:white;box-shadow:0 4px 11px #4d815d30}.secondary-button:disabled{opacity:.55;cursor:default}.action-sub{display:block;font-size:8px;font-weight:500;opacity:.76;margin-top:3px}.capture-success{padding:10px}.toast{position:fixed;z-index:10;bottom:22px;left:50%;transform:translate(-50%,20px);padding:11px 16px;background:#324e3b;color:white;border-radius:12px;font-size:11px;box-shadow:0 8px 25px #182a1c38;opacity:0;pointer-events:none;transition:.25s;white-space:nowrap}.toast.show{opacity:1;transform:translate(-50%,0)}
@media(max-width:900px){.app-shell{padding:0 24px 18px}.layout{grid-template-columns:minmax(0,1.25fr) minmax(300px,.85fr);gap:17px}.journal-card{padding:18px 15px 13px}.collection-grid{gap:6px}.creature-slot{min-height:69px}.welcome-row h1{font-size:30px}}
