@media(prefers-reduced-motion:reduce){*,*:before,*:after{animation-duration:.01ms!important;transition-duration:.01ms!important;scroll-behavior:auto!important}}

const zones=[
 {name:'Dewdrop Grove',icon:'🌱',desc:'A soft green beginning, where the shy ones peek out.',note:'Every creature has a favorite snack. A little kindness goes a long way.',colors:['#d9edc9','#a8ce9a','#80b77f','#d4e5ac'],creatures:['Mosskip','Pipkin','Dewdrop','Bramblebun','Mushmew','Fernling']},
 {name:'Sunpetal Fields',icon:'🌼',desc:'Golden flowers, warm breezes, and bright little spirits.',note:'The sunniest friends love a good stretch in a warm patch of light.',colors:['#f6e8aa','#e8c66d','#a9c87a','#f7d88e'],creatures:['Pollenpuff','Sunkit','Mariglow','Buzzlet','Honeyhop','Dandyfox']},
 {name:'Misty Brook',icon:'💧',desc:'Follow the babbling water to find the gentle swimmers.',note:'Listen closely by the water. Some friends answer with a tiny song.',colors:['#d6ecdf','#90c8bd','#70aaa7','#c3ded0'],creatures:['Ripplefin','Lilybit','Pebblit','Drizzle','Bubblemew','Reedling']},
 {name:'Twilight Thicket',icon:'🌙',desc:'A hush falls here, and little lanterns begin to glow.',note:'Twilight friends are shy. Slow movements make them feel safe.',colors:['#ded9e9','#988bb2','#6e8192','#c9bbd2'],creatures:['Duskit','Moonmoth','Glimmerfox','Noctowl','Velvetail','Starwhisk']},
 {name:'Cloudberry Ridge',icon:'☁️',desc:'Up above the treetops, the sky is full of surprises.',note:'The ridge is breezy! Your new friends might just float beside you.',colors:['#dcebf0','#9fc3d0','#82a9c0','#f0d7ad'],creatures:['Cloudlet','Skydoodle','Thistledown','Cometkit','Windwhirl','Aurorabbit']}
];
const roster=[
 ['🍃','A tiny mossy wanderer who loves a soft hello.','Common','leaf'],['🐸','A bouncy little friend with a song for every puddle.','Common','round'],['💧','A dewdrop sprite that sparkles in the morning light.','Common','round'],['🐰','A gentle burrower who collects fallen flower petals.','Uncommon','ears'],['🍄','A sleepy mushroom pal. It naps whenever it rains.','Uncommon','cap'],['🌿','A sproutling who grows a little taller with each friend.','Rare','leaf'],
 ['🐝','A pollen puff with wings that hum a happy tune.','Common','wings'],['🦊','A sun-kissed kit who follows warm rays across the field.','Common','ears'],['🌻','A golden glowbud that turns to greet each new face.','Uncommon','cap'],['🐞','A speedy buzzlet with tiny polka-dot wings.','Common','wings'],['🍯','A honey-sweet hopper who shares every snack.','Uncommon','round'],['🦊','A dandy fox with a bright bloom tucked behind one ear.','Rare','ears'],
 ['🐟','A ripplefin who makes silver rings in the brook.','Common','fins'],['🪷','A lilybit that drifts wherever the current takes it.','Common','round'],['🪨','A pebblit, sturdy as a stone and twice as kind.','Uncommon','round'],['🌧️','A little drizzle cloud that carries its own rainbows.','Common','cloud'],['🫧','A bubble-loving friend who giggles underwater.','Uncommon','round'],['🌾','A reedling who sways along to the brook’s rhythm.','Rare','leaf'],
 ['🌑','A duskit who only comes out when the sky turns violet.','Common','ears'],['🦋','A moonmoth whose wings shine like a quiet night sky.','Uncommon','wings'],['🦊','A glimmerfox with a tail that glows in the dark.','Rare','tail'],['🦉','A thoughtful no-owl who knows all the forest stories.','Common','round'],['🐈','A velvetail with the softest paws in the thicket.','Uncommon','ears'],['✨','A starwhisk who leaves tiny sparkles wherever it goes.','Legendary','stars'],
 ['☁️','A cloudlet that floats along, looking for someone to wave at.','Common','cloud'],['🐦','A skydoodle who draws loops in the breeze.','Common','wings'],['🪶','A thistledown who drifts gently from hill to hill.','Uncommon','cloud'],['☄️','A cometkit makes a wish every time it streaks by.','Rare','tail'],['🌬️','A windwhirl who dances with the mountain breeze.','Uncommon','wings'],['🌈','An aurorabbit, a once-in-a-meadow friend with a rainbow glow.','Legendary','ears']
].map((data,i)=>({id:i,name:zones[Math.floor(i/6)].creatures[i%6],emoji:data[0],description:data[1],rarity:data[2],shape:data[3],zone:Math.floor(i/6),color:['#83a96e','#e7ba6b','#85b6ad','#988db2','#88b5bf','#cf9368','#8cae65','#e6a56c','#e4bf64','#d69073','#d4a84e','#d28e78','#7eafad','#9bbf97','#a99c83','#93b3cc','#a7c8c0','#93a768','#7985a6','#9a8fc1','#d18e93','#96a1b5','#b184a5','#b9a2dd','#a4c5d0','#84aabc','#b6c8c6','#dd9b76','#8bb7bc','#e58bb2'][i]}));
const SAVE_KEY='mosslight-meadow-v1';let state={caught:[],berries:8,sparks:0,zone:0,affinity:0,encounter:null,expanded:false};
try{const saved=JSON.parse(localStorage.getItem(SAVE_KEY)||'{}');state={...state,...saved,caught:Array.isArray(saved.caught)?saved.caught:[]}}catch{}
const $=s=>document.querySelector(s),canvas=$('#meadow'),ctx=canvas.getContext('2d');let sprites=[],sceneW=0,sceneH=0,toastTimer,frame=0;
function save(){localStorage.setItem(SAVE_KEY,JSON.stringify({caught:state.caught,berries:state.berries,sparks:state.sparks,zone:state.zone}))}
function showToast(text){const el=$('#toast');el.textContent=text;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2100)}
function makeZoneTabs(){const el=$('#zone-tabs');el.innerHTML=zones.map((z,i)=>`<button class="zone-tab ${i===state.zone?'active':''}" data-zone="${i}"><span>${z.icon}</span>${z.name}</button>`).join('');el.querySelectorAll('button').forEach(b=>b.onclick=()=>setZone(+b.dataset.zone))}
function setZone(i){state.zone=i;makeZoneTabs();$('#zone-name').textContent=zones[i].name;$('#zone-desc').textContent=zones[i].desc;$('#field-note-text').textContent=zones[i].note;drawScene();save()}
function renderJournal(){const count=state.caught.length;$('#caught-count').textContent=count;$('#journal-footer-total').textContent=`${count} / 30`;
 $('#progress-fill').style.width=`${count/30*100}%`;$('#spark-count').textContent=state.sparks;$('#berry-count').textContent=state.berries;
 $('#progress-quip').textContent=count===0?'The first hello is always the sweetest.':count<6?'A lovely little collection is taking shape.':count<15?'The meadow is starting to feel like home.':count<30?'So many new friends, and more still to meet!':'You found every friend in the meadow! What a lovely world.';
 const all=state.expanded?roster:roster.slice(0,15);$('#collection-grid').innerHTML=all.map(c=>{const got=state.caught.includes(c.id);return `<button class="creature-slot ${got?'new-friend':'unknown'}" data-creature="${c.id}" aria-label="${got?c.name:'Undiscovered creature'}">${got?`<span class="slot-art">${c.emoji}</span><span class="slot-name">${c.name}</span>`:`<span class="slot-art">?</span><span class="slot-name">???</span>`}</button>`}).join('');$('#collection-grid').querySelectorAll('button').forEach(b=>b.onclick=()=>{const c=roster[+b.dataset.creature];if(state.caught.includes(c.id))showCreatureInfo(c);else showToast('A mystery friend! Explore their home to meet them.')});$('#journal-expand').innerHTML=state.expanded?'Show less <span>↑</span>':'View all <span>↗</span>'}
$('#journal-expand').onclick=()=>{state.expanded=!state.expanded;renderJournal()};
function resizeCanvas(){const rect=canvas.getBoundingClientRect();const dpr=Math.min(devicePixelRatio||1,2);canvas.width=Math.round(rect.width*dpr);canvas.height=Math.round(rect.height*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);sceneW=rect.width;sceneH=rect.height;drawScene()}
function rnd(seed){let x=Math.sin(seed*127.1+state.zone*311.7)*43758.5453;return x-Math.floor(x)}
function drawScene(){if(!sceneW||!sceneH)return;const w=sceneW,h=sceneH,z=zones[state.zone],p=z.colors;ctx.clearRect(0,0,w,h);
 const sky=ctx.createLinearGradient(0,0,0,h);sky.addColorStop(0,p[0]);sky.addColorStop(.64,p[0]);sky.addColorStop(1,p[1]);ctx.fillStyle=sky;ctx.fillRect(0,0,w,h);
 // soft distant hills
 ctx.fillStyle=p[1];ctx.beginPath();ctx.moveTo(0,h*.53);ctx.bezierCurveTo(w*.18,h*.31,w*.29,h*.52,w*.48,h*.42);ctx.bezierCurveTo(w*.69,h*.27,w*.8,h*.51,w,h*.36);ctx.lineTo(w,h);ctx.lineTo(0,h);ctx.fill();
 ctx.fillStyle=p[2];ctx.beginPath();ctx.moveTo(0,h*.67);ctx.bezierCurveTo(w*.22,h*.51,w*.34,h*.7,w*.53,h*.58);ctx.bezierCurveTo(w*.74,h*.47,w*.85,h*.7,w,h*.56);ctx.lineTo(w,h);ctx.lineTo(0,h);ctx.fill();
 // winding path
 ctx.fillStyle=state.zone===2?'#cfddd0':'#d8d9ae';ctx.beginPath();ctx.moveTo(w*.36,h);ctx.bezierCurveTo(w*.43,h*.8,w*.62,h*.76,w*.56,h*.57);ctx.bezierCurveTo(w*.51,h*.43,w*.71,h*.46,w*.77,h*.42);ctx.bezierCurveTo(w*.64,h*.56,w*.62,h*.53,w*.67,h*.72);ctx.bezierCurveTo(w*.76,h*.87,w*.58,h*.93,w*.57,h);ctx.fill();
 // far trees / bushes
 for(let i=0;i<13;i++){const x=rnd(i+3)*w,y=h*(.34+rnd(i+13)*.13),r=10+rnd(i+23)*15;ctx.globalAlpha=.35+rnd(i+8)*.25;ctx.fillStyle=i%2?p[2]:p[3];ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1;
 // flowers and grass
